PORTS.forEach(p=>p.harbor=seaPoint(p.harbor.x,p.harbor.z));
export const RUIN={x:-25.8,z:-37.4,r:.5,name:"Azores — Lost Observatory",harbor:seaPoint(-27,-37.4)};
export function newGame(){return{version:2,story:freshStory(),gold:1200,supplies:30,hull:100,cargo:{saffron:0,silk:0,timber:0,wine:0},x:PORTS[0].harbor.x,z:PORTS[0].harbor.z,heading:-.55,time:480,quest:0,discovered:[],log:['Day 1 — Took command of The Wayfarer at Lisbon.'],sail:0};}
export function cargoCount(s){return Object.values(s.cargo).reduce((a,b)=>a+b,0);}
export function trade(s,port,id,side){if(!GOODS.some(g=>g.id===id))return{ok:false,message:'Unknown cargo.'};const price=side==='buy'?port.prices[id]:Math.floor(port.prices[id]*.85);if(side==='buy'){if(cargoCount(s)>=40)return{ok:false,message:'Your hold is full. Sell cargo to make room.'};if(s.gold<price)return{ok:false,message:'Not enough gold.'};s.gold-=price;s.cargo[id]++;if(s.quest===0&&s.cargo.saffron>=3){s.quest=1;s.log.push('Bought the saffron. Set course for London.');}}else if(side==='sell'){if(!s.cargo[id])return{ok:false,message:'None of this cargo in your hold.'};s.cargo[id]--;s.gold+=price;if(id==='saffron'&&port.id==='london'&&s.quest===1){s.delivered=(s.delivered||0)+1;if(s.delivered>=3){s.quest=2;s.gold+=500;s.log.push('Delivered saffron to London. Earned a 500 gold commission.');return{ok:true,message:'Commission complete! +500 gold. Seek the Azores Observatory.'};}}}else return{ok:false,message:'Invalid trade.'};return{ok:true,message:`${side==='buy'?'Bought':'Sold'} ${GOODS.find(g=>g.id===id).name} for ${price} gold.`};}
export function loadGame(storage){try{const s=JSON.parse(storage.getItem('horizon-save'));if(!s||![1,2].includes(s.version))return newGame();const legacy=s.version===1;if(legacy){s.version=2;s.x=PORTS[0].harbor.x;s.z=PORTS[0].harbor.z;s.discovered=[];s.log=['Your existing cargo and gold have arrived in Lisbon.'];}const valid=Number.isFinite(s.gold)&&s.gold>=0&&Number.isFinite(s.x)&&Math.abs(s.x)<=179&&Number.isFinite(s.z)&&s.z>=-78&&s.z<=65&&Number.isFinite(s.heading)&&Number.isFinite(s.time)&&Number.isFinite(s.supplies)&&s.supplies>=0&&Number.isFinite(s.hull)&&s.hull>0&&s.hull<=100&&[0,1,2,3].includes(s.quest)&&Array.isArray(s.log)&&Array.isArray(s.discovered)&&GOODS.every(g=>Number.isInteger(s.cargo?.[g.id])&&s.cargo[g.id]>=0)&&cargoCount(s)<=40;return valid?{...newGame(),...s,story:restoreStory(s.story),sail:0}:newGame();}catch{return newGame();}}
export function saveGame(storage,s){try{storage.setItem('horizon-save',JSON.stringify(s));return true;}catch{return false;}}
